import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
}

const STATUS_FILTERS: Array<{ value: ProjectStatus; label: string }> = [
  { value: 'active', label: 'Активные' },
  { value: 'paused', label: 'На паузе' },
  { value: 'over', label: 'Превышен лимит' },
];

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' }
> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышен лимит', tone: 'danger' },
};

const PAGE_SIZE = 5;

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекст-лаборатория', used: 412, quota: 500, status: 'active' },
  { id: 'p2', name: 'Индексация документов', used: 96, quota: 400, status: 'paused' },
  { id: 'p3', name: 'Разметка диалогов', used: 540, quota: 500, status: 'over' },
  { id: 'p4', name: 'Поиск по базе знаний', used: 210, quota: 300, status: 'active' },
  { id: 'p5', name: 'Мониторинг качества ответов', used: 45, quota: 250, status: 'paused' },
  { id: 'p6', name: 'Экспорт отчётов', used: 178, quota: 200, status: 'active' },
  { id: 'p7', name: 'Синхронизация с хранилищем', used: 620, quota: 450, status: 'over' },
  { id: 'p8', name: 'Дашборд расхода', used: 88, quota: 350, status: 'active' },
  { id: 'p9', name: 'Архив старых прогонов', used: 12, quota: 150, status: 'paused' },
  { id: 'p10', name: 'Эксперименты с промптами', used: 265, quota: 300, status: 'active' },
  { id: 'p11', name: 'Очистка обучающих выборок', used: 330, quota: 400, status: 'active' },
];

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([
    'active',
    'paused',
    'over',
  ]);
  const [page, setPage] = useState(1);

  const visibleProjects = useMemo(
    () =>
      activeStatuses.length === 0
        ? []
        : PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(visibleProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const rows = visibleProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  const removeStatus = (status: ProjectStatus) => {
    setActiveStatuses((previous) => previous.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUS_FILTERS.map((filter) => filter.value));
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Расход квоты по проектам
        </h2>
        <p style={{ margin: 0, fontSize: '14px', color: 'var(--jx-text-2)' }}>
          Снимите фильтр, чтобы скрыть проекты с этим статусом.
        </p>
      </div>

      <div
        role="group"
        aria-label="Фильтры по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {STATUS_FILTERS.filter((filter) => activeStatuses.includes(filter.value)).map(
          (filter) => (
            <JxChip
              key={filter.value}
              active
              removable
              onRemove={() => removeStatus(filter.value)}
            >
              {filter.label}
            </JxChip>
          ),
        )}
        {activeStatuses.length < STATUS_FILTERS.length && (
          <JxButton variant="ghost" size="sm" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        )}
      </div>

      {rows.length === 0 ? (
        <JxEmptyState
          title="Проектов с такими фильтрами нет"
          message="Все статусы сняты или под фильтр ничего не подошло. Верните фильтры, чтобы снова увидеть список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {rows.map((project) => {
              const meta = STATUS_META[project.status];
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 14px',
                    background: 'var(--jx-surface-2)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <JxProgressCircle
                    value={project.used}
                    max={project.quota}
                    showValue
                    aria-label={`Заполненность квоты проекта ${project.name}`}
                  />
                  <div style={{ flex: '1 1 auto', minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: '15px',
                        color: 'var(--jx-text)',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      {project.name}
                    </div>
                    <div
                      style={{
                        fontSize: '13px',
                        color: 'var(--jx-text-2)',
                        fontFamily: 'var(--jx-font-mono)',
                      }}
                    >
                      {project.used} / {project.quota}
                    </div>
                  </div>
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <JxPagination
            total={pageCount}
            page={currentPage}
            onPageChange={setPage}
            aria-label="Страницы списка проектов"
          />
        </>
      )}
    </section>
  );
}

